1	package events
2	
3	import (
4		"sort"
5		"strings"
6		"sync"
7	)
8	
9	// BeforeCommit persists a batch of brand-new events. It runs while the
10	// timeline lock is held and before the batch becomes visible to queries, so a
11	// successful return guarantees the batch is durable and committed atomically.
12	// Returning an error rejects the batch without touching the timeline.
13	type BeforeCommit func(persisted []Event) error
14	
15	// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
16	// whole batches and reports replays of already-stored events.
17	type Timeline struct {
18		mu     sync.RWMutex
19		byID   map[string]Event
20		events []Event
21	}
22	
23	// NewTimeline returns an empty timeline.
24	func NewTimeline() *Timeline {
25		return &Timeline{byID: make(map[string]Event)}
26	}
27	
28	// IngestResult counts how a batch was applied: Created events are new,
29	// Replayed events matched an existing event with the same id and content.
30	type IngestResult struct {
31		Created  int
32		Replayed int
33	}
34	
35	// Ingest normalizes and validates every event first, then checks the whole
36	// batch against existing events and itself. Validation failures produce a
37	// ValidationError; duplicate ids with differing content, or a repeated id
38	// within the batch, produce a ConflictError. Nothing is stored when an error
39	// is returned.
40	//
41	// New events are passed to beforeCommit for durable storage; only after it
42	// succeeds does the batch become visible, so concurrent readers see either
43	// the complete batch or none of it.
44	func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
45		normalized := make([]Event, len(batch))
46		for i, event := range batch {
47			norm, err := Normalize(event)
48			if err != nil {
49				return IngestResult{}, err
50			}
51			normalized[i] = norm
52		}
53	
54		t.mu.Lock()
55		defer t.mu.Unlock()
56	
57		pending := make(map[string]struct{}, len(normalized))
58		var created []Event
59		var result IngestResult
60		for _, event := range normalized {
61			if _, repeated := pending[event.ID]; repeated {
62				return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
63			}
64			pending[event.ID] = struct{}{}
65			if existing, ok := t.byID[event.ID]; ok {
66				if !sameEvent(existing, event) {
67					return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
68				}
69				result.Replayed++
70				continue
71			}
72			created = append(created, event)
73			result.Created++
74		}
75	
76		if len(created) > 0 {
77			if beforeCommit != nil {
78				if err := beforeCommit(created); err != nil {
79					return IngestResult{}, err
80				}
81			}
82			for _, event := range created {
83				t.byID[event.ID] = event
84				t.events = append(t.events, event)
85			}
86			sort.SliceStable(t.events, func(i, j int) bool {
87				return byTimeThenID(t.events[i], t.events[j])
88			})
89		}
90		return result, nil
91	}
92	
93	// Load inserts events recovered from durable storage during startup. Every
94	// event must already be normalized; a duplicate id with differing content is
95	// reported as a conflict so the caller can fail rather than mutate data.
96	func (t *Timeline) Load(event Event) error {
