1	// Package logfile persists event batches as an append-only sequence of
2	// length-prefixed, CRC-checked frames.
3	//
4	// Frame layout (all integers big-endian):
5	//
6	//	[4 bytes payload length][4 bytes CRC32-IEEE of payload][payload bytes]
7	//
8	// The payload is a JSON array encoded with events.MarshalBatch.
9	package logfile
10	
11	import (
12		"encoding/binary"
13		"errors"
14		"fmt"
15		"hash/crc32"
16		"os"
17		"path/filepath"
18		"sync"
19	
20		"github.com/cocosolocoder/signalroom/internal/events"
21	)
22	
23	const (
24		logName  = "events.log"
25		lockName = "lock"
26	
27		headerSize = 8
28		// maxPayload guards against absurd allocations when a corrupt length
29		// prefix happens to point inside the file.
30		maxPayload = 64 << 20
31	)
32	
33	// ErrPoisoned is returned after a write or sync failure. The log refuses all
34	// further writes until the process is restarted and recovery succeeds.
35	var ErrPoisoned = errors.New("event log is unavailable after a storage failure")
36	
37	// Log is an append-only, concurrency-safe frame writer holding an exclusive
38	// directory lock for its lifetime.
39	type Log struct {
40		mu       sync.Mutex
41		file     *os.File
42		lockFile *os.File
43		poisoned bool
44	}
45	
46	// CorruptionError marks a complete frame that fails its checksum or contains
47	// illegal data, as opposed to an incomplete trailing frame.
48	type CorruptionError struct{ Reason string }
49	
50	func (e *CorruptionError) Error() string { return e.Reason }
51	
52	func corruption(format string, args ...any) error {
53		return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
54	}
55	
56	// Open acquires an exclusive lock on the data directory, creates it if
57	// needed, replays the log, and truncates at most one incomplete trailing
58	// frame (a torn final write). A corrupt frame in the middle, or a complete
59	// frame containing illegal data, is fatal: Open returns an error without
60	// modifying the file.
61	//
62	// Recovered batches are returned in write order, ready to load into a
63	// timeline.
64	func Open(dir string) (*Log, [][]events.Event, error) {
65		if dir == "" {
66			return nil, nil, errors.New("data directory is required")
67		}
68		if err := os.MkdirAll(dir, 0o755); err != nil {
69			return nil, nil, fmt.Errorf("create data directory: %w", err)
70		}
71	
72		lockPath := filepath.Join(dir, lockName)
73		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
74		if err != nil {
75			return nil, nil, fmt.Errorf("open directory lock: %w", err)
76		}
77		if err := tryLock(lockFile); err != nil {
78			lockFile.Close()
79			if errors.Is(err, errLocked) {
80				return nil, nil, fmt.Errorf("data directory %q is in use by another signalroom instance", dir)
81			}
82			return nil, nil, fmt.Errorf("acquire directory lock: %w", err)
83		}
84	
85		path := filepath.Join(dir, logName)
86		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
87		if err != nil {
88			unlock(lockFile)
89			lockFile.Close()
90			return nil, nil, fmt.Errorf("open event log: %w", err)
91		}
92	
93		batches, validLen, err := replay(file)
94		if err != nil {
95			file.Close()
96			unlock(lockFile)
97			lockFile.Close()
98			return nil, nil, err
99		}
100		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
101			// Drop exactly one incomplete trailing frame. This is the only
102			// mutation recovery performs, so it is fsynced before serving.
103			if err := file.Truncate(validLen); err != nil {
104				file.Close()
105				unlock(lockFile)
106				lockFile.Close()
107				return nil, nil, fmt.Errorf("truncate incomplete trailing frame: %w", err)
108			}
109			if err := file.Sync(); err != nil {
110				file.Close()
111				unlock(lockFile)
112				lockFile.Close()
113				return nil, nil, fmt.Errorf("sync event log: %w", err)
114			}
115		}
116		if err := syncDir(dir); err != nil {
117			file.Close()
118			unlock(lockFile)
119			lockFile.Close()
120			return nil, nil, fmt.Errorf("sync data directory: %w", err)
121		}
122	
123		return &Log{file: file, lockFile: lockFile}, batches, nil
124	}
125	
126	// replay scans the log and returns the valid batches, the byte offset at
127	// which the log is known good, and an error for any corruption before that
128	// offset.
129	func replay(file *os.File) ([][]events.Event, int64, error) {
130		data, err := os.ReadFile(file.Name())
131		if err != nil {
132			return nil, 0, fmt.Errorf("read event log: %w", err)
133		}
134	
135		var batches [][]events.Event
136		pos := int64(0)
137		for pos < int64(len(data)) {
138			remaining := int64(len(data)) - pos
139			if remaining < headerSize {
140				// Torn partial header: ignore everything from here on.
141				break
142			}
143			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
144			if payloadLen <= 0 || payloadLen > maxPayload {
145				return nil, 0, corruption("corrupt frame header at offset %d", pos)
146			}
147			frameEnd := pos + headerSize + payloadLen
148			if frameEnd > int64(len(data)) {
149				// Header landed but its payload did not: torn trailing frame.
150				break
151			}
152			payload := data[pos+headerSize : frameEnd]
153			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
154			if crc32.ChecksumIEEE(payload) != wantCRC {
155				return nil, 0, corruption("checksum mismatch at offset %d", pos)
156			}
157			batch, err := events.DecodeBatch(payload)
158			if err != nil {
159				return nil, 0, corruption("illegal frame payload at offset %d: %v", pos, err)
160			}
161			if len(batch) == 0 {
162				return nil, 0, corruption("empty batch frame at offset %d", pos)
163			}
164			for i := range batch {
165				normalized, err := events.Normalize(batch[i])
166				if err != nil {
167					return nil, 0, corruption("invalid event in frame at offset %d: %v", pos, err)
168				}
169				batch[i] = normalized
170			}
171			batches = append(batches, batch)
172			pos = frameEnd
173		}
174		return batches, pos, nil
175	}
176	
177	// Append durably writes one batch. The bytes hit the disk (write followed by
178	// fsync) before Append returns. Any write or sync failure poisons the log:
179	// this call and every later one return ErrPoisoned until restart.
180	func (l *Log) Append(batch []events.Event) (err error) {
181		payload, err := events.MarshalBatch(batch)
182		if err != nil {
183			return fmt.Errorf("encode batch: %w", err)
184		}
185		if len(payload) > maxPayload {
186			return fmt.Errorf("batch exceeds %d byte frame limit", maxPayload)
187		}
188	
189		frame := make([]byte, headerSize+len(payload))
190		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
191		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
192		copy(frame[headerSize:], payload)
193	
194		l.mu.Lock()
195		defer l.mu.Unlock()
196		if l.poisoned {
197			return ErrPoisoned
198		}
199		defer func() {
200			if err != nil {
201				l.poisoned = true
202			}
203		}()
204	
205		if _, err = l.file.Write(frame); err != nil {
206			return fmt.Errorf("write event log: %w", err)
207		}
208		if err = l.file.Sync(); err != nil {
209			return fmt.Errorf("sync event log: %w", err)
210		}
211		return nil
212	}
213	
214	// Poisoned reports whether the log has suffered an unrecoverable write error.
215	func (l *Log) Poisoned() bool {
216		l.mu.Lock()
217		defer l.mu.Unlock()
218		return l.poisoned
219	}
220	
221	// Close releases the log and the exclusive directory lock.
222	func (l *Log) Close() error {
223		l.mu.Lock()
224		defer l.mu.Unlock()
225		var closeErr error
226		if err := l.file.Close(); err != nil {
227			closeErr = err
228		}
229		if err := unlock(l.lockFile); err != nil && closeErr == nil {
230			closeErr = err
231		}
232		if err := l.lockFile.Close(); err != nil && closeErr == nil {
233			closeErr = err
234		}
235		return closeErr
236	}
237

