194		tl := NewTimeline()
195		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
196		var commits int64
197		commit := func(created []Event) error {
198			atomic.AddInt64(&commits, 1)
199			return nil
200		}
