81	// startServer launches serve on an ephemeral port and blocks until the
82	// readiness line publishes the real address — no fixed sleeps.
83	func startServer(t *testing.T, dataDir string) *serverProc {
84		t.Helper()
85		logs := &safeBuffer{}
86		cmd := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
87		stdout, err := cmd.StdoutPipe()
88		if err != nil {
89			t.Fatal(err)
90		}
91		stderr, err := cmd.StderrPipe()
92		if err != nil {
93			t.Fatal(err)
94		}
95		if err := cmd.Start(); err != nil {
96			t.Fatalf("start serve: %v", err)
97		}
98		waitCh := make(chan error, 1)
99		done := make(chan struct{})
100		go func() {
101			waitCh <- cmd.Wait()
102			close(done)
103		}()
104	
105		ready := make(chan string, 1)
106		scan := func(r io.Reader) {
107			scanner := bufio.NewScanner(r)
108			for scanner.Scan() {
109				line := scanner.Text()
110				logs.Write([]byte(line + "\n"))
111				if addr, ok := strings.CutPrefix(line, "signalroom: listening on "); ok {
112					select {
113					case ready <- strings.TrimSpace(addr):
114					default:
115					}
116				}
117			}
118		}
119		go scan(stdout)
120		go scan(stderr)
121	
122		select {
123		case addr := <-ready:
124			proc := &serverProc{cmd: cmd, addr: addr, logs: logs, waitCh: waitCh, done: done}
125			t.Cleanup(func() { proc.killIfAlive() })
126			return proc
127		case err := <-waitCh:
128			t.Fatalf("serve exited before becoming ready (%v); output:\n%s", err, logs.String())
129			return nil
130		case <-time.After(5 * time.Second):
131			t.Fatalf("server never became ready; output:\n%s", logs.String())
132			return nil
133		}
134	}
